  pfwork: { lead: 'B351', layers: [{ p: 'GBM', k: 'primer', rate: 0.4, coats: 1 }, { p: 'QS', k: 'sand', rate: 1.0, coats: 1 }, { p: 'B351', k: 'coat', rate: 1.4, mm: true, coats: 1 }, { p: 'V2260', k: 'puseal', rate: 0.115, coats: 1, opt: 'pu' }, { p: 'ANTI', k: 'anti', rate: 0.011, coats: 1, opt: 'pu' }, { p: 'IPU', k: 'joint', joint: true }, { p: 'K4031', k: 'rep', rep: 1.7 }] },
  pfhall: { lead: 'B351', layers: [{ p: 'GBM', k: 'primer', rate: 0.4, coats: 2 }, { p: 'QS', k: 'sand', rate: 1.0, coats: 1 }, { p: 'B351', k: 'thick', rate: 1.2, mm: true, coats: 1 }, { p: 'QS', k: 'thickSand', rate: 0.6, mm: true, coats: 1 }, { p: 'B351', k: 'inter', rate: 0.35, coats: 1, opt: true }, { p: 'QS', k: 'broadcast', rate: 1.5, coats: 1, opt: true }, { p: 'B351', k: 'topseal', rate: 0.6, coats: 1, opt: true }, { p: 'IPU', k: 'joint', joint: true }, { p: 'EV200', k: 'rep', rep: 1.9 }] },
