    function push(t) { if (!t) return; var text = decode(t); if (out.length && out[out.length - 1].b === b && !out[out.length - 1].br) out[out.length - 1].text += text; else out.push({ text: text, b: b }); }
    while ((m = re.exec(s))) { push(s.slice(last, m.index)); last = re.lastIndex; var close = m[1] === '/', tag = (m[2] || '').toLowerCase(); if (tag === 'b' || tag === 'strong') b += close ? -1 : 1; else if (tag === 'br') out.push({ text: '\n', b: b, br: true }); if (b < 0) b = 0; }
