    var g = LOGO.logo, W = 1200, H = Math.round(W * g.h / g.w), c = mkc(W, H), q = c.getContext('2d'); q.scale(W / g.w, W / g.w); q.fillStyle = '#e3000f'; q.fill(new Path2D(g.d));
