    'rc.lcc.model': 'The model', 'rc.lcc.area': 'Area', 'rc.lcc.horizon': 'Planning horizon', 'rc.lcc.rate': 'Discount rate', 'rc.lcc.years': 'years', 'rc.lcc.pct': '%', 'rc.lcc.perm2': 'per m²', 'rc.lcc.perm2y': 'per m² and year', 'rc.lcc.uM2': '/m²', 'rc.lcc.uM2y': '/m²·yr',
