  try { var st = JSON.parse(localStorage.getItem('aquafin-p4-wp') || 'null'); if (st) { if (WPS[st.scn]) scn = st.scn; if (WPP[st.prod]) prod = st.prod; if (st.calc) { for (var ck in calc) if (typeof st.calc[ck] === typeof calc[ck]) calc[ck] = st.calc[ck]; touched = !!st.touched; } } } catch (e) {}
