    h += '<section class="sec" id="rc-procedure"><div class="wrap">' + head('p', 'rc.tl.label', 'rc.tl.title') + scnbar('rcSelProc') +
      '<div class="tl-bar"><p class="sec-sub" id="rcTlSub"></p><div class="tl-ctrl">' + icoBtn('rcTlPrev', 'rc.tl.prev', 'M15 5l-7 7 7 7') + icoBtn('rcTlNext', 'rc.tl.next', 'M9 5l7 7-7 7') + '</div></div><div class="tl" id="rcTl" tabindex="0"></div></div></section>';
    h += '<section class="sec sec--band" id="rc-model3d"><div class="wrap">' + head('m', 'rc.m3d.label', 'rc.m3d.title') + '<p class="sec-sub" id="rcM3dSub"></p>' + scnbar('rcSelM3d') + '<div class="m3d-bar"><div class="seg seg--scroll" id="rcM3dTabs" role="group"></div><div class="m3d-tools"><button class="sb-btn sb-btn--secondary" type="button" id="rcXray" aria-pressed="false" data-rc="rc.m3d.xray"></button><button class="sb-btn sb-btn--secondary" type="button" id="rcMicro" aria-pressed="false" data-rc="m3d.micro"></button>' + icoBtn('rcZoomIn', 'rc.m3d.zin', 'M12 5v14M5 12h14') + icoBtn('rcZoomOut', 'rc.m3d.zout', 'M5 12h14') + '<button class="sb-btn sb-btn--secondary" type="button" id="rcReset" data-rc="rc.m3d.reset"></button></div></div>' +
      '<div class="stage3d" id="rcM3dStage" style="background:var(--surface)"><canvas role="img"></canvas><div class="stage3d__cap"><div class="stage3d__capbox"><span id="rcM3dNum">—</span><span id="rcM3dCap"></span></div></div><div class="m3d-hint" data-rc="rc.m3d.hint"></div><div class="stage3d__fallback" id="rcM3dFallback" hidden data-rc="rc.m3d.fallback"></div></div><p class="m3d-note muted" id="rcM3dNote" hidden></p><div class="callouts" id="rcCallouts"></div></div></section>';
    h += (typeof HSIM !== 'undefined' ? HSIM.gate('rc') : '');
    h += '<section class="sec" id="rc-products"><div class="wrap">' + head('d', 'rc.prod.label', 'rc.prod.title') + '<p class="sec-sub" data-rc="rc.prod.sub"></p><div class="cr-ptabs rc-ptabs" id="rcPtabs" role="tablist"></div><div class="cr-prod" id="rcProd" role="tabpanel"></div></div></section>';
    h += '<section class="sec sec--band" id="rc-calculator"><div class="wrap">' + head('c', 'rc.calc.label', 'rc.calc.title') + '<p class="sec-sub" data-rc="rc.calc.sub"></p><div class="calc cr-calc"><form class="calc__form" id="rcCalcForm" novalidate></form><div class="calc__preview" id="rcCalcOut" aria-live="polite"></div></div></div></section>';
    h += '<section class="sec sec--band" id="rc-documents"><div class="wrap"><div class="sec-head"><div><p class="sec-head__kicker" id="rcDocsKicker"></p><h2 class="sec-head__h" id="rcDocsTitle"></h2></div>' + signet(21) + '</div><p class="sec-sub" id="rcDocsSub"></p><div class="docs" id="rcDocs"></div></div></section>';
    h += '<section class="sec" id="rc-compare"><div class="wrap">' + head('k', 'rc.cmp.label', 'rc.cmp.title') + '<p class="sec-sub" data-rc="rc.cmp.sub"></p><div class="sb-table-wrap"><table class="sb-table cmp cr-cmp rc-cmp" id="rcCmp"></table></div><h3 class="sub-h" data-rc="rc.rel.title"></h3><p class="sec-sub" data-rc="rc.rel.sub" style="margin-bottom:0"></p><div class="prows" id="rcRel"></div></div></section>';
