    $('caCallouts').innerHTML = tr('ca.m3d.co')[scn].map(function (c) { return '<div class="callout"><h3>' + tx(c[0]) + '</h3><p>' + tx(c[1]) + '</p></div>'; }).join('');
    var xb = $('caXray'); xb.setAttribute('aria-pressed', xray || st[m3d] === 'heal' ? 'true' : 'false'); if (st[m3d] === 'heal') xb.setAttribute('aria-disabled', 'true'); else xb.removeAttribute('aria-disabled');
    document.querySelector('#caM3dStage canvas').setAttribute('aria-label', tr('ca.m3d.aria'));
    var tb = $('caM3dTabs'), b = tb.querySelector('[aria-pressed="true"]'); if (b && tb.scrollWidth > tb.clientWidth) tb.scrollLeft = Math.max(0, b.offsetLeft - (tb.clientWidth - b.offsetWidth) / 2);
