    setTimeout(function () { try { $('caDiagram').innerHTML = secStageMarkup(); secView = new CAView($('caSecStage'), { mode: 'cut', scenario: scn }); secView.setStage(stage, true); secShown = scn + ':' + stage; secView.onRender = drawSecCallouts; window.caSection = secView; drawSecCallouts(); queueSnaps(); } catch (e) { if (window.console) console.error('admixture section 3D', e); secView = null; $('caDiagram').innerHTML = section(scn, stage, false); } }, 260);
