      quote: function () { var r = compute(), lines = [], basis = [], PK = tr('ca.pk'); if (!r.ok) return { lines: [], basis: [], warn: [] }; basis.push([tr('ca.calc.vol'), fmt(num(calc.vol), 1) + ' m³']); basis.push([tr('ca.calc.cem'), fmt(num(calc.cem), 0) + ' kg/m³']); basis.push([tr('ca.calc.pct'), fmt(r.pct, 2) + ' % = ' + fmt(r.kgM3, 2) + ' kg/m³']); basis.push([tr('ca.calc.where'), tr(calc.where === 'truck' ? 'ca.calc.truck' : 'ca.calc.plant')]); basis.push([tr('ca.calc.allow'), fmt(num(calc.allow), 0) + ' %']); lines.push({ p: calc.p, name: plain('{' + calc.p + '}'), use: tr('ca.calc.pct') + ' ' + fmt(r.pct, 2) + ' % (' + fmt(r.kgM3, 2) + ' kg/m³)', qty: r.total, unit: 'kg', packs: r.packs, packLabel: function (q) { return q[1] + ' kg ' + (PK[q[2]] || q[2]); } }); return { lines: lines, basis: basis, warn: r.warn.map(plain) }; },
