/* (V84) a region that scrolls sideways (a wide table on a narrow screen, the mechanism diagram) must be reachable by keyboard: it gets a tab stop
   only while it actually overflows, re-checked after every render and resize */
var _sfT = null;
function scrollFocus() { [].forEach.call(document.querySelectorAll('.sb-table-wrap, .diagram'), function (el) { if (el.scrollWidth > el.clientWidth + 1) { if (!el.hasAttribute('tabindex')) { el.setAttribute('tabindex', '0'); var c = el.querySelector('caption, h3, h2'); if (c && c.textContent.trim()) { el.setAttribute('role', 'region'); el.setAttribute('aria-label', c.textContent.trim()); } } } else if (el.getAttribute('tabindex') === '0') { el.removeAttribute('tabindex'); el.removeAttribute('role'); el.removeAttribute('aria-label'); } }); }
function scrollFocusSoon() { clearTimeout(_sfT); _sfT = setTimeout(scrollFocus, 250); }
window.addEventListener('resize', scrollFocusSoon);
