  $('m3dZoomIn').addEventListener('click', function () { if (inspector) inspector.zoom(0.85); }); $('m3dZoomOut').addEventListener('click', function () { if (inspector) inspector.zoom(1.18); }); $('m3dReset').addEventListener('click', function () { if (inspector) inspector.reset(); });

